solution.solution.cpp:
#include <set>
#include <string>

bool breaksBinaryCompatibility(const std::string& change)
{
    static const std::set<std::string> safe{ "add a function", "add a result code", "change an opaque type's members", "add an enum value at the end", "fix a bug" };
    return safe.count(change) == 0;
}

unitTests:
TEST("breaking") { CHECK(breaksBinaryCompatibility("remove a function")); CHECK(breaksBinaryCompatibility("change a parameter type")); CHECK(breaksBinaryCompatibility("reorder struct members")); CHECK(breaksBinaryCompatibility("renumber an enum value")); CHECK(breaksBinaryCompatibility("change a visible struct's size")); }
TEST("safe") { CHECK(!breaksBinaryCompatibility("add a function")); CHECK(!breaksBinaryCompatibility("add a result code")); CHECK(!breaksBinaryCompatibility("change an opaque type's members")); CHECK(!breaksBinaryCompatibility("add an enum value at the end")); CHECK(!breaksBinaryCompatibility("fix a bug")); }
TEST("unknown means assume the worst") { CHECK(breaksBinaryCompatibility("something else")); }

